"""Publish immutable physical assembly evidence and concise operational documentation."""
from pathlib import Path
import argparse,datetime,hashlib,json,re,zipfile
ROOT=Path(__file__).resolve().parents[1];BASE=ROOT/'artifacts/analog_asic'
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def rel(p):return p.relative_to(ROOT).as_posix()
def atomic(p,b):
 tmp=p.with_suffix('.tmp');tmp.write_bytes(b);tmp.replace(p)
def main():
 ap=argparse.ArgumentParser();ap.add_argument('--cell',required=True);ap.add_argument('--revision',type=int,required=True);ap.add_argument('--report',required=True);ap.add_argument('--role',required=True);ap.add_argument('--gate',required=True);ap.add_argument('--note',required=True);a=ap.parse_args();old=BASE/'assembly'/f'article_module_catalog_v{a.revision-1}.json';cp=BASE/'assembly'/f'article_module_catalog_v{a.revision}.json';assert not cp.exists();cat=json.loads(old.read_text());assert all(sha(ROOT/n)==h for n,h in cat['sha256'].items());assert a.cell not in [x['cell'] for x in cat['characterization_assemblies']]
 rp=ROOT/a.report;r=json.loads(rp.read_text());assert r['module_simulation_completed'] and a.gate in r;folder=BASE/'layout'/a.cell;qs=[folder/n for n in ['qualification.json','flat_cap_qualification.json','abstract_qualification.json']];q,f,aq=[json.loads(p.read_text()) for p in qs];assert q['magic_drc_count']==0 and q['lvs_unique'] and q['gds_roundtrip_drc_count']==0 and q['gds_roundtrip_lvs_unique'] and f['flat_lvs_unique'] and not f['negative_aggregate_branches'] and aq['physical_ports_and_size_verified']
 for d in [r,f,aq]:
  for n,h in d['sha256'].items():
   if Path(n).suffix!='.ext':assert sha(ROOT/n)==h,n
 files=[*qs,rp,folder/(a.cell+'.gds'),folder/(a.cell+'.lef'),folder/(f['flat_subcircuit']+'_cap.spice')];entry={'cell':a.cell,'role':a.role,'dense_resident_leaf':False,'complete_neuron_functionally_accepted':False,'mos_count':q['mos_count'],'native_mim_count':q.get('native_mim_count',0),'native_resistor_count':q.get('native_resistor_count',0),'ports':q['ports'],'bbox_um':q['bbox_um'],'module_layout_and_nominal_simulation_artifacts_complete':True,'nominal_gate':a.gate,'nominal_gate_pass':bool(r[a.gate]),'views':{p.name:rel(p) for p in files},'limitations':r['scope']+' '+a.note};cat['characterization_assemblies'].append(entry);cat['revision']=a.revision;cat['previous_catalog']=rel(old);cat['sha256'].update({rel(p):sha(p) for p in files});cat['next_assembly']='Complete connected analog adaptation/energy/threshold/readout functions, global control and dense full25actor hierarchy. Preserve nominal imperfections; original-float accuracy and full-population5ms acceptance remain incomplete.';cp.write_text(json.dumps(cat,indent=2)+'\n');n=len(cat['modules']);m=len(cat['characterization_assemblies'])
 bp=BASE/'results'/(a.cell+'_article_boundary.json');assert not bp.exists();audit={'catalog':rel(cp),'modules':n,'characterization_assemblies':m,'nominal_gate':a.gate,'nominal_gate_pass':bool(r[a.gate]),'cases':r.get('cases',[]),'limitations':entry['limitations'],'full_chip_layout_complete':False,'original_float_accuracy_accepted':False,'full_5ms_population_service_accepted':False,'sha256':{rel(p):sha(p) for p in [cp,*files,Path(__file__)]}};bp.write_text(json.dumps(audit,indent=2)+'\n')
 docs=[ROOT/'docs'/fn for fn in ['AGENTS.md','ACTIVE_TASKS.md','ARCHITECTURE.md','DECISIONS.md','RESULTS.md','PROGRESS.md','project_spec.yaml']];stamp=datetime.datetime.now(datetime.timezone.utc).strftime('%Y%m%dT%H%M%SZ');zp=BASE/'documentation_history'/('project_docs_before_'+a.cell+'_'+stamp+'.zip')
 with zipfile.ZipFile(zp,'x',zipfile.ZIP_DEFLATED) as z:
  for p in docs:z.writestr(rel(p),p.read_bytes())
 zp.with_suffix('.json').write_text(json.dumps({'archive_sha256':sha(zp),'files':{rel(p):{'bytes':p.stat().st_size,'sha256':sha(p)} for p in docs}},indent=2)+'\n')
 title=a.role.replace('_',' ')
 def insert(name,text):
  p=ROOT/'docs'/name;b=p.read_bytes();i=b.index(b'\n## ');atomic(p,b[:i]+text.encode('utf-8')+b[i:])
 insert('RESULTS.md',f'\n## {title} - 2026-10-10\n\n[Assembly boundary](../{rel(bp)}) records {a.cell}: {q["mos_count"]} native MOS, {q.get("native_resistor_count",0)} resistors and {q.get("native_mim_count",0)} MIMs; full DRC0/LVS, GDS reimport and real LEF, {f["linear_branch_count"]} nonnegative flat capacitance branches. Nominal simulation completed; `{a.gate}={bool(r[a.gate])}`. {a.note}\n\n{r["scope"]} Catalog revision{a.revision}: {n} module artifact sets/{m} characterization assemblies. Full goal remains incomplete.\n')
 insert('ARCHITECTURE.md',f'\n## {title} physical connection - 2026-10-10\n\n{q["scope"]} {a.note} Nominal gate:{bool(r[a.gate])}; local circuit evidence does not establish original-float population behavior or5ms service.\n')
 insert('PROGRESS.md',f'\n{title}: native physical and extracted nominal artifacts complete; catalog revision{a.revision}, {n} module sets/{m} characterization assemblies. {a.note} Full objective incomplete. Exact prior docs: `{rel(zp)}`.\n')
 p=ROOT/'docs/ACTIVE_TASKS.md';b=p.read_bytes().replace(old.name.encode(),cp.name.encode()).replace(f'catalog revision{a.revision-1}'.encode(),f'catalog revision{a.revision}'.encode());b=re.sub(rb'\*\*Physical module completion and assembly\.\*\* [^\r\n]+',f'**Physical module completion and assembly.** {n} reusable GF180 module artifact sets and {m} routed characterization assemblies have physical checks and completed nominal simulations. Complete neuron functionality, dense arrays and full-chip layout remain unfinished.'.encode(),b,count=1);b=re.sub(rb'\| Latest evidence \|[^\r\n]+',f'| Latest evidence | {n} reusable module artifact sets and {m} characterization assemblies in catalog revision{a.revision}; measured imperfections retained |'.encode(),b,count=1);b=re.sub(rb'\| Job status \|[^\r\n]+',f'| Job status | {a.cell} physical and nominal evidence complete; gate={bool(r[a.gate])}; next connected analog support and dense/full assembly |'.encode(),b,count=1);b=re.sub(rb'1\. [0-9]+ reusable physical modules[^\r\n]+',f'1. {n} reusable physical modules and {m} characterization assemblies have layout checks and nominal extracted simulations recorded in catalog revision{a.revision}. Preserve measured imperfections; no repeated precision sweep.'.encode(),b,count=1);b=re.sub(rb'contains [0-9]+ completed module view/simulation sets and [0-9]+ characterization assemblies',f'contains {n} completed module view/simulation sets and {m} characterization assemblies'.encode(),b,count=1);atomic(p,b)
 p=ROOT/'docs/project_spec.yaml';b=p.read_bytes();head,tail=b.split(b'\ndocument:',1);head=head.replace(old.name.encode(),cp.name.encode());head=re.sub(rb'  evidence: [^\r\n]+',b'  evidence: '+rel(bp).encode(),head,count=1);head=re.sub(rb'  live_sessions: [^\r\n]+',b'  live_sessions: []',head,count=1);head=re.sub(rb'    report: [^\r\n]+',b'    report: '+rel(bp).encode(),head,count=1);head=re.sub(rb'    status: [^\r\n]+',f'    status: {n}_modules_{m}_assemblies_latest_nominal_artifacts_complete_accuracy_unaccepted'.encode(),head,count=1);atomic(p,head+b'\ndocument:'+tail)
 print(json.dumps({'catalog':rel(cp),'boundary':rel(bp),'modules':n,'assemblies':m},indent=2))
if __name__=='__main__':main()
